import{_ as t,o,c as n,a2 as a}from"./chunks/framework.Dss97255.js";const u=JSON.parse(`{"title":"Troubleshooting: Connection Issues","description":"Diagnose problems with creating, using, or removing connections","frontmatter":{"title":"Troubleshooting: Connection Issues","description":"Diagnose problems with creating, using, or removing connections","audience":["operator","user"],"symptoms":["bot doesn't respond","no notifications","duplicate messages","connection not created"]},"headers":[],"relativePath":"troubleshooting/connection-issues.md","filePath":"troubleshooting/connection-issues.md","lastUpdated":1775243305000}`),s={name:"troubleshooting/connection-issues.md"};function i(c,e,r,d,h,l){return o(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="connection-issues" tabindex="-1">Connection Issues <a class="header-anchor" href="#connection-issues" aria-label="Permalink to &quot;Connection Issues&quot;">​</a></h1><p>The bot isn&#39;t responding to commands, connections aren&#39;t being created, notifications aren&#39;t appearing, or you&#39;re getting duplicates.</p><h2 id="check-1-is-the-bot-in-the-room" tabindex="-1">Check 1: Is the bot in the room? <a class="header-anchor" href="#check-1-is-the-bot-in-the-room" aria-label="Permalink to &quot;Check 1: Is the bot in the room?&quot;">​</a></h2><p>The hookshot bot must be a member of the room. Check the room member list for <code>@hookshot:yourdomain</code> (or your configured bot localpart).</p><p>If not present:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>/invite @hookshot:yourdomain</span></span></code></pre></div><p>The bot should auto-accept the invite. If it doesn&#39;t, check hookshot logs for invite handling errors.</p><h2 id="check-2-does-the-bot-have-sufficient-power-level" tabindex="-1">Check 2: Does the bot have sufficient power level? <a class="header-anchor" href="#check-2-does-the-bot-have-sufficient-power-level" aria-label="Permalink to &quot;Check 2: Does the bot have sufficient power level?&quot;">​</a></h2><p>The bot needs:</p><ul><li>PL 0 (default member) to send messages and read state</li><li>Higher PL if the room requires it for state events</li></ul><p>Check room settings → Roles and Permissions. The bot should not be restricted.</p><h2 id="check-3-are-there-connections-in-this-room" tabindex="-1">Check 3: Are there connections in this room? <a class="header-anchor" href="#check-3-are-there-connections-in-this-room" aria-label="Permalink to &quot;Check 3: Are there connections in this room?&quot;">​</a></h2><p>List all connections:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>!hookshot list</span></span></code></pre></div><p>If no connections appear:</p><ul><li>Create one: <code>!hookshot github repo &lt;url&gt;</code>, <code>!hookshot webhook &lt;name&gt;</code>, etc.</li><li>Check your permission level — you need <code>manageConnections</code> to create connections</li></ul><p>If <code>!hookshot list</code> gets no response at all, the bot may not be receiving messages. Check logs at <code>debug</code> level.</p><h2 id="check-4-is-the-command-prefix-correct" tabindex="-1">Check 4: Is the command prefix correct? <a class="header-anchor" href="#check-4-is-the-command-prefix-correct" aria-label="Permalink to &quot;Check 4: Is the command prefix correct?&quot;">​</a></h2><p>Each connection type has its own prefix:</p><table tabindex="0"><thead><tr><th>Integration</th><th>Prefix</th><th>Example</th></tr></thead><tbody><tr><td>Setup commands</td><td><code>!hookshot</code></td><td><code>!hookshot github repo ...</code></td></tr><tr><td>GitHub repo</td><td><code>!gh</code> (default)</td><td><code>!gh create &quot;Bug&quot;</code></td></tr><tr><td>GitLab repo</td><td><code>!gl</code> (default)</td><td><code>!gl create &quot;Issue&quot;</code></td></tr><tr><td>JIRA project</td><td><code>!jira</code> (default)</td><td><code>!jira create &quot;Ticket&quot;</code></td></tr><tr><td>OpenProject</td><td><code>!op</code> (default)</td><td><code>!op create &quot;WP&quot;</code></td></tr></tbody></table><p>The prefix can be customized per connection via the <code>commandPrefix</code> option. Check <code>!hookshot list</code> for the configured prefix.</p><h2 id="check-5-duplicate-messages" tabindex="-1">Check 5: Duplicate messages <a class="header-anchor" href="#check-5-duplicate-messages" aria-label="Permalink to &quot;Check 5: Duplicate messages&quot;">​</a></h2><p>If you&#39;re receiving the same notification multiple times:</p><ol><li><strong>Multiple connections to the same resource.</strong> Run <code>!hookshot list</code> — if you see the same repo/project connected twice, remove the duplicate.</li><li><strong>Multiple hookshot instances</strong> pointed at the same homeserver. Check for duplicate processes.</li><li><strong>Room aliases</strong> — if the same room is accessible via multiple aliases, it&#39;s still one room (not a duplication cause).</li></ol><h2 id="check-6-connection-creation-fails" tabindex="-1">Check 6: Connection creation fails <a class="header-anchor" href="#check-6-connection-creation-fails" aria-label="Permalink to &quot;Check 6: Connection creation fails&quot;">​</a></h2><p>When <code>!hookshot github repo &lt;url&gt;</code> or similar fails:</p><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>&quot;You do not have permission&quot;</td><td>Permission level below <code>manageConnections</code></td><td>Admin: upgrade permission level</td></tr><tr><td>&quot;GitHub is not configured&quot;</td><td>No <code>github</code> section in config</td><td>Operator: add service config</td></tr><tr><td>&quot;Could not find repository&quot;</td><td>Wrong URL or App not installed on that repo</td><td>Check URL, install GitHub App</td></tr><tr><td>No response at all</td><td>Bot not in room, or command parsing failed</td><td>Check bot membership, check logs</td></tr></tbody></table><h2 id="check-7-events-enabled-but-no-notifications" tabindex="-1">Check 7: Events enabled but no notifications <a class="header-anchor" href="#check-7-events-enabled-but-no-notifications" aria-label="Permalink to &quot;Check 7: Events enabled but no notifications&quot;">​</a></h2><p>For service-specific connections (GitHub, GitLab, etc.), events can be individually enabled/disabled.</p><p>GitHub defaults to 13 of 23 event types. For example, <code>push</code> events are <strong>disabled by default</strong>.</p><p>Check current config via room state or <code>!hookshot list</code>. To enable more events, update the connection config via widget, API, or state event.</p><h2 id="check-8-connection-state-in-matrix" tabindex="-1">Check 8: Connection state in Matrix <a class="header-anchor" href="#check-8-connection-state-in-matrix" aria-label="Permalink to &quot;Check 8: Connection state in Matrix&quot;">​</a></h2><p>Connections are stored as room state events. You can inspect them directly:</p><p>In Element: Room Settings → Advanced → Room State → look for <code>uk.half-shot.matrix-hookshot.*</code> events.</p><p>If the state event exists but the connection isn&#39;t working, hookshot may not have picked it up. Restart hookshot — it reconstructs all connections from state on startup.</p><h2 id="check-9-hookshot-logs" tabindex="-1">Check 9: Hookshot logs <a class="header-anchor" href="#check-9-hookshot-logs" aria-label="Permalink to &quot;Check 9: Hookshot logs&quot;">​</a></h2><p>Set <code>logging.level: debug</code> and look for:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span># Connection created successfully:</span></span>
<span class="line"><span>info: New connection created for room !abc:example.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Connection not found for event:</span></span>
<span class="line"><span>debug: No connections found for github event</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Command received but not handled:</span></span>
<span class="line"><span>debug: Command not handled: !gh unknown</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./webhooks-not-arriving">Webhooks Not Arriving</a> — Webhook-specific diagnostics</li><li><a href="./authentication">Authentication</a> — OAuth and token problems</li><li><a href="./../understand/integration-model">Integration Model</a> — How connections work</li><li><a href="./">Troubleshooting Index</a></li></ul>`,40)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
